<?php require __DIR__.'/config/config.php'; if(empty($_SESSION['user_id'])){header('Location:index.php');exit;} $u=db()->prepare('SELECT * FROM users WHERE id=?');$u->execute([$_SESSION['user_id']]);$u=$u->fetch();$site=setting('site_name','Rishtewale');$target=$u['gender']==='male'?'female':'male';$limit=$u['gender']==='male'?30:20;$s=db()->prepare("SELECT * FROM profiles WHERE gender=? AND active=1 AND city=? ORDER BY RAND() LIMIT $limit");$s->execute([$target,$u['city']]);$profiles=$s->fetchAll(); if(!$profiles){$s=db()->prepare("SELECT * FROM profiles WHERE gender=? AND active=1 ORDER BY RAND() LIMIT $limit");$s->execute([$target]);$profiles=$s->fetchAll();} ?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($site)?></title><link rel="stylesheet" href="assets/style.css"></head><body><main class="phone"><header><b>💗 <?=h($site)?></b><a href="logout.php">Logout</a></header><section class="welcome"><span>Welcome, <?=h($u['name'])?></span><h1>📍 <?=h($u['city'])?>, <?=h($u['state'])?></h1><p>आपके शहर के लिए profiles</p></section><div class="profile-list"><?php foreach($profiles as $p): $img=$p['photo'] ?: (($p['gender']==='female') ? "https://randomuser.me/api/portraits/women/".(($p['id']*7)%90).".jpg" : "https://randomuser.me/api/portraits/men/".(($p['id']*7)%90).".jpg"); ?><a class="profile-row" href="profile.php?id=<?=$p['id']?>"><img src="<?=h($img)?>" alt="<?=h($p['name'])?>"><div class="profile-main"><b><?=h($p['name'])?>, <?=h($p['age'])?> <i>✓</i></b><span>📍 <?=h($p['city'])?>, <?=h($p['state'])?></span><span>💼 <?=h($p['about'] ?: "Professional")?></span><small>● Online</small></div><strong class="heart">♡</strong></a><?php endforeach;?></div></main><script src="/rishtewale-protection.js"></script>
